CREATE   VIEW [isurv].[vwIsurv_Product_Group] AS

SELECT
 P.PRODUCTNUMBER AS 'Product Number'
,Product_Name AS 'Product'
,CASE
	WHEN P.PRODUCTNUMBER IN ('ISURV00000','ISURV00000','ISURV00000','ISURV00000') THEN 'isurv APC/AssocRICS'
	WHEN P.PRODUCTNUMBER IN ('ISURV0000') THEN 'isurv Basic Planning'
	WHEN P.PRODUCTNUMBER IN ('ISURV0000','ISURV0000','ISURV7799Bolton') THEN 'isurv Building Surveying'
	WHEN P.PRODUCTNUMBER IN ('ISURV0000','ISURV0000','ISURV7120Bolton') THEN 'isurv Commercial Property'
	WHEN P.PRODUCTNUMBER IN ('ISURV0000','ISURV0000','ISURV7268Bolton','ISURV00000') THEN 'isurv Construction'
	WHEN P.PRODUCTNUMBER IN ('ISURV0000') THEN 'isurv Environment'
	WHEN P.PRODUCTNUMBER IN ('ISURV00000','ISURV00000','ISURV00000','ISURV18094CP','ISURV18094C') THEN 'isurv Flex'
	WHEN P.PRODUCTNUMBER IN ('ISURV00000','ISURV20553Bolton','ISURV00000') THEN 'isurv Infrastructure'
	WHEN P.PRODUCTNUMBER IN ('ISURV00000') THEN 'isurv legal'
	WHEN P.PRODUCTNUMBER IN ('ISURV00000','ISURV18159CP','ISURV00000','ISURV00000') THEN 'isurv One'
	WHEN P.PRODUCTNUMBER IN ('ISURV0000','ISURV7986Bolton') THEN 'isurv Planning'
	WHEN P.PRODUCTNUMBER IN ('ISURV0000','ISURV7774CP','ISURV7774C','ISURV0000') THEN 'isurv Professional'
	WHEN P.PRODUCTNUMBER IN ('ISURV00000','ISURV20001Bolton','ISURV00000') THEN 'isurv Professional Conduct'
	WHEN P.PRODUCTNUMBER IN ('ISURV00000','ISURV00000','ISURV17972Bolton','ISURV00000') THEN 'isurv Residential'
	WHEN P.PRODUCTNUMBER IN ('ISURV00000','ISURV18671Bolton','ISURV00000') THEN 'isurv Rural'
	WHEN P.PRODUCTNUMBER IN ('ISURV18157CP','ISURV00000') THEN 'isurv Study - APC'
	WHEN P.PRODUCTNUMBER IN ('ISURV00000','ISURV18672Bolton','ISURV00000') THEN 'isurv Sustainability'
	WHEN P.PRODUCTNUMBER IN ('ISURV00000','ISURV00000') THEN 'isurv Uni'
	WHEN P.PRODUCTNUMBER IN ('ISURV0000','ISURV0000','ISURV7274Bolton','ISURV00000') THEN 'isurv Valuation'
	ELSE 'Other' END AS 'isurv Product Group'

FROM FO.vwProduct P
WHERE P.PRODUCTNUMBER LIKE '%isurv%'
